use std::cmp::Ordering;

// EVOLVE-BLOCK-START
# HYPOTHESIS-1: Switching to Rust's stable slice::sort_unstable will improve performance_score and avg_time by using an optimized introsort without extra allocations.
# MECHANISM-1: The standard library implementation is heavily optimized (branching, pivoting, insertion-sort cutoff) and avoids Clone-based pivot copies.
# EXPECT-1: performance_score > 0.985
# RESULT-1: REFUTED (actual=0.0)
# HYPOTHESIS-2: Removing unused helper functions and Clone bounds will improve score by reducing code size and trait constraints while preserving correctness.
