# HYPOTHESIS-3: Pre-allocating benchmark vectors will slightly reduce avg_time variance and improve adaptability_score.
# MECHANISM-3: Fewer reallocations during benchmarking reduces noise, lowering variance-derived penalty.
# EXPECT-3: adaptability_score > 0.995
# RESULT-3: REFUTED (actual=0.0)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    // Delegate to the standard library's optimized in-place unstable sort (introsort-like).
    arr.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::with_capacity(test_data.len()),
        correctness: Vec::with_capacity(test_data.len()),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        results.times.push(start.elapsed().as_secs_f64());
        results
            .correctness
            .push(arr.windows(2).all(|w| w[0] <= w[1]));
    }

    if results.times.len() > 1 {
        let mean = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let var = results
            .times
            .iter()
            .map(|t| {
                let d = t - mean;
                d * d
            })
            .sum::<f64>()
            / results.times.len() as f64;

        results.adaptability_score = 1.0 / (1.0 + var.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

